        if hs.size > 0 and hs.sum() > 0:
            r = _R(hs)
            if r > best_R:
                best_R = r
                best_h = hs.copy()

    rng = np.random.default_rng(12345)

    def make_full(x, N):
        h = np.empty(N)
        h[0] = 1.0
        h[1:] = np.exp(x)
        return h

    def negR(x, N):
        return -_R(make_full(x, N))

    Ns = [2, 3, 5, 10, 20]
    for N in Ns:
        if time.process_time() > deadline:
            break
        # starting points
        starts = []
        # geometric 0.5^i
        starts.append(np.log(0.5 ** np.arange(1, N)))
        # linear (N-i)/N
        lin = np.array([(N - i) / N for i in range(1, N)])
