    for N in (2, 3, 4, 5, 7, 10, 14, 20, 28, 40, 60, 100):
        Ns.add(N)
    Ns = sorted(Ns)

    # Local polish on the start itself (full-length optimization)
    if best_h is not None and best_h.size >= 2 and time.process_time() < deadline:
        h0 = np.maximum(best_h, 1e-12)
