import numpy as np
import time

def compute_R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    a = np.concatenate(([0.0], L, [0.0]))
    l2 = np.sum(a[:-1] ** 2 + a[:-1] * a[1:] + a[1:] ** 2) / 3.0
    linf = a.max()
    if linf <= 0:
        return 0.0
    return l2 / (s * s * linf)

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = np.ones(50)
    best_R = compute_R(best)
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size >= 1 and s.size <= 50000 and np.all(np.isfinite(s)) and np.all(s >= 0) and s.sum() > 0:
            r = compute_R(s)
            if r > best_R:
                best = s.copy()
                best_R = r

    rng = np.random.default_rng(12345)

    def try_candidate(h):
        nonlocal best, best_R
        h = np.asarray(h, dtype=float)
        if h.size > 50000 or h.sum() <= 0 or not np.all(np.isfinite(h)):
            return
        r = compute_R(h)
        if r > best_R:
            best_R = r
            best = h.copy()

    # Smooth bump parametric families across resolutions
    for N in [50, 80, 120, 200, 320, 500, 800, 1200]:
        x = np.linspace(-1, 1, N)
        for p in [1, 1.5, 2, 2.5, 3, 4, 6]:
            try_candidate(np.exp(-(np.abs(x) ** p) * 4.0))
        for a in [0.2, 0.4, 0.6]:
            h = np.maximum(0.0, 1 - a * np.abs(x) ** 2 - (1 - a) * np.abs(x) ** 4)
            try_candidate(h)

    # Coordinate-wise local search with multiplicative/additive perturbations
    def local_search(h, iters, scale):
        h = h.copy()
        n = h.size
        cur_R = compute_R(h)
        for _ in range(iters):
            if time.process_time() > deadline:
                break
            idx = rng.integers(0, n)
            old = h[idx]
            if rng.random() < 0.5:
                h[idx] = max(0.0, old * (1.0 + scale * rng.standard_normal()))
            else:
                h[idx] = max(0.0, old + scale * rng.standard_normal() * (h.mean() + 1e-9))
            r = compute_R(h)
            if r > cur_R:
                cur_R = r
            else:
                h[idx] = old
        return h, cur_R

    # Multi-resolution refinement: doubles resolution then polishes
    def multi_res(h, r, levels=3):
        nonlocal best, best_R
        cur_h, cur_r = h.copy(), r
        for _ in range(levels):
            if time.process_time() > deadline:
                break
            n = cur_h.size
            if n < 50000:
                new_n = min(n * 2, 50000)
                cur_h = np.interp(np.linspace(0, n - 1, new_n), np.arange(n), cur_h)
                cur_h = np.clip(cur_h, 0.0, None)
                cur_r = compute_R(cur_h)
            h2, r2 = local_search(cur_h, iters=40000, scale=0.2)
            if r2 > cur_r:
                cur_h, cur_r = h2, r2
        return cur_h, cur_r

    # Refine the current best
    if time.process_time() < deadline:
        h, r = multi_res(best, best_R)
        if r > best_R:
            best, best_R = h, r

    # Try multiple starting shapes
    seeds = []
    for N in [50, 100, 200, 400]:
        x = np.linspace(-1, 1, N)
        for p in [1.5, 2, 3]:
            seeds.append(np.exp(-(np.abs(x) ** p) * 3.0))
    for h0 in seeds:
        if time.process_time() > deadline:
            break
        r0 = compute_R(h0)
        h, r = multi_res(h0, r0, levels=2)
        if r > best_R:
            best, best_R = h, r

    # Final polish
    if time.process_time() < deadline:
        for sc in [0.1, 0.05, 0.02]:
            if time.process_time() > deadline:
                break
            h, r = local_search(best, iters=30000, scale=sc)
            if r > best_R:
                best, best_R = h, r

    return np.asarray(best, dtype=float)

