        for b in betas:
            if time.process_time() > deadline:
                break
            h = make(a, b)
            r = _R(h)
            if r > best_R:
                best_R = r
                best_ab = (a, b)
        if time.process_time() > deadline:
            break

    # Nelder-Mead refinement
    def negR(x):
        return -_R(make(x[0], x[1]))

    if time.process_time() < deadline:
        try:
            res = minimize(negR, np.array(best_ab), method='Nelder-Mead',
                           options={'xatol': 1e-4, 'fatol': 1e-8,
                                    'maxiter': 500, 'maxfev': 500})
            if -res.fun > best_R:
                best_R = -res.fun
                best_ab = (res.x[0], res.x[1])
        except Exception:
            pass

    h = make(*best_ab)
    # sanity
    if not np.all(np.isfinite(h)) or h.sum() <= 0:
        h = make(-0.5, 0.0)
    return h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    conv = fftconvolve(h, h)
    L = np.empty(conv.size + 2)
    L[0] = 0.0
    L[1:-1] = conv
    L[-1] = 0.0
    m = L.max()
    if m <= 0:
        return 0.0
    L2 = (L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2).sum() / 3.0
    return L2 / (s * s * m)


def _hb(N):
    h = np.empty(N, dtype=float)
    h[0] = 1.0
    for n in range(N - 1):
        h[n + 1] = h[n] * (2.0 * n + 1.0) / (2.0 * n + 2.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 50000
    hb = _hb(N)

    best_h = hb.copy()
    best_R = _R(hb)

    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        if hs.size > 0 and hs.sum() > 0:
            rs = _R(hs)
            if rs > best_R:
                best_R = rs
                best_h = hs.copy()

    # Multi-scale perturbation search: add smooth oscillatory/edge corrections
    # to hb via low-frequency basis, optimized coordinate-wise with restarts.
    x = np.arange(N, dtype=float) / N

    def make_h(coefs, scales):
        # scales: list of (freq, power); coefs length = sum of basis dims
        logh = np.zeros(N)
        idx = 0
        for (freq, power) in scales:
            for k in range(1, power + 1):
                logh += coefs[idx] * np.cos(np.pi * freq * k * x)
                idx += 1
            for k in range(1, power + 1):
                logh += coefs[idx] * np.sin(np.pi * freq * k * x)
                idx += 1
        return hb * np.exp(logh)

    # Progressive refinement: several basis configurations, greedy coordinate ascent
    configs = [
        [(1, 3)],
        [(1, 3), (2, 2)],
        [(1, 4), (2, 3), (3, 2)],
        [(1, 5), (2, 4), (3, 3), (4, 2)],
    ]

    rng = np.random.default_rng(12345)

    for scales in configs:
        if time.process_time() > deadline:
            break
        dim = sum(2 * p for (_, p) in scales)
        coefs = np.zeros(dim)
        curR = _R(hb)
        step = 0.05
        # coordinate ascent with random order, a few sweeps
        for sweep in range(30):
            if time.process_time() > deadline:
                break
            improved = False
            order = rng.permutation(dim)
            for i in order:
                if time.process_time() > deadline:
                    break
                for delta in (step, -step):
                    trial = coefs.copy()
                    trial[i] += delta
                    h = make_h(trial, scales)
                    r = _R(h)
                    if r > curR + 1e-9:
                        curR = r
                        coefs = trial
                        improved = True
                        break
            if not improved:
                step *= 0.5
                if step < 1e-4:
                    break
        h = make_h(coefs, scales)
        r = _R(h)
        if r > best_R:
            best_R = r
            best_h = h

    # Final polishing with Powell on top of best basis if time permits
    if time.process_time() < deadline:
        try:
            scales = configs[-1]
            dim = sum(2 * p for (_, p) in scales)
            # recover coefs approximately by fitting log(best_h/hb) via lstsq
            logr = np.log(np.maximum(best_h, 1e-300) / hb)
            A = []
            for (freq, power) in scales:
                for k in range(1, power + 1):
                    A.append(np.cos(np.pi * freq * k * x))
                for k in range(1, power + 1):
                    A.append(np.sin(np.pi * freq * k * x))
            A = np.stack(A, axis=1)
            coefs, _, _, _ = np.linalg.lstsq(A, logr, rcond=None)

            def negR(c):
                return -_R(make_h(c, scales))

            res = minimize(negR, coefs, method='Powell',
                           options={'maxiter': 60, 'xtol': 1e-6, 'ftol': 1e-9})
            h = make_h(res.x, scales)
            r = _R(h)
            if r > best_R:
                best_R = r
                best_h = h
        except Exception:
            pass

    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        if hs.size > 0 and hs.sum() > 0:
            if _R(hs) > best_R:
                return hs

    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 0.0
    conv = np.convolve(h, h)
    L = np.empty(conv.size + 2)
    L[0] = 0.0
    L[1:-1] = conv
    L[-1] = 0.0
    m = L.max()
    if m <= 0:
        return 0.0
    L2 = (L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2).sum() / 3.0
    return L2 / (s * s * m)


def _R_fast(h):
    """FFT-based R for larger arrays."""
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 0.0
    conv = fftconvolve(h, h)
    L = np.empty(conv.size + 2)
    L[0] = 0.0
    L[1:-1] = conv
    L[-1] = 0.0
    m = L.max()
    if m <= 0:
        return 0.0
    L2 = (L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2).sum() / 3.0
    return L2 / (s * s * m)


def _refine(h0, deadline, rfunc, n_rounds=6):
    """Coordinate ascent: optimize each height in log-space with Powell-like
    scalar line search. Very robust for small/moderate N."""
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    if h.sum() <= 0:
        return h, 0.0
    best_R = rfunc(h)
    N = h.size
    # Normalize so max = 1 for stability
    h = h / h.max()
    best_R = rfunc(h)
    for _ in range(n_rounds):
        if time.process_time() > deadline:
            break
        improved = False
        # Order: alternate forward/backward sweeps
        for i in range(N):
            if time.process_time() > deadline:
                break
            cur = h[i]
            if cur <= 0:
                cur = 1e-9
            # Test multiplicative factors around cur
            best_local = best_R
            best_val = cur
            for f in (0.5, 0.7, 0.85, 1.15, 1.4, 2.0):
                h[i] = cur * f
                r = rfunc(h)
                if r > best_local:
                    best_local = r
                    best_val = cur * f
            h[i] = cur
            if best_local > best_R + 1e-14:
                h[i] = best_val
                best_R = best_local
                improved = True
        if not improved:
            break
    return h, best_R


def _lbfgs_polish(h0, deadline, rfunc, maxiter=300):
    """L-BFGS-B in log-space on all entries."""
    h = np.maximum(np.asarray(h0, dtype=float), 1e-9)
    N = h.size
    x0 = np.log(h)
    def build(x):
        return np.exp(np.clip(x, -30.0, 30.0))
    def negR(x):
        return -rfunc(build(x))
    best_h = h.copy()
    best_R = rfunc(h)
    try:
        res = minimize(negR, x0, method='L-BFGS-B',
                       bounds=[(-25.0, 5.0)] * N,
                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-12})
        cand = build(res.x)
        r = rfunc(cand)
        if r > best_R:
            best_R = r
            best_h = cand
    except Exception:
        pass
    return best_h, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_R = -1.0

    # Track the best start
    start_h = None
    start_R = -1.0
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and np.all(np.isfinite(hs)) and hs.max() > 0:
            hs = np.maximum(hs, 0.0)
            r = _R_fast(hs) if hs.size > 500 else _R(hs)
            if r > start_R:
                start_R = r
                start_h = hs.copy()
            if r > best_R:
                best_R = r
                best_h = hs.copy()

    rng = np.random.default_rng(1234567)

    # Generate candidate seeds. The optimum for small N tends to be a sharp
    # peak with structured tails. Try many N and shapes.
    def _seed_tent(N):
        i = np.arange(N)
        c = (N - 1) / 2.0
        return np.maximum(1.0 - np.abs(i - c) / (c + 1e-9), 0.02)

    def _seed_geom(N, ratio):
        return ratio ** np.arange(N)

    def _seed_ones(N):
        return np.ones(N)

    def _seed_parab(N):
        i = np.arange(N)
        c = (N - 1) / 2.0
        return np.maximum(1.0 - ((i - c) / (c + 1e-9)) ** 2, 0.02)

    # Candidate list: (N, seed)
    candidates = []
    for N in range(3, 61):
        candidates.append((N, _seed_tent(N)))
        candidates.append((N, _seed_parab(N)))
        candidates.append((N, _seed_geom(N, 0.6)))
        candidates.append((N, _seed_geom(N, 0.8)))
        candidates.append((N, _seed_ones(N)))
    if start_h is not None:
        candidates.append((start_h.size, start_h.copy()))

    # Phase 1: quick coordinate ascent on each candidate
    for (N, seed) in candidates:
        if time.process_time() > deadline * 0.7:
            break
        rfunc = _R if N <= 400 else _R_fast
        h, r = _refine(seed, deadline, rfunc, n_rounds=4)
        if r > best_R:
            best_R = r
            best_h = h.copy()

    # Phase 2: L-BFGS polish on the best few sizes
    if best_h is not None:
        # Try polishing best at its current N, plus neighbors
        N0 = best_h.size
        for N in [N0, N0 - 1, N0 + 1]:
            if N < 2 or time.process_time() > deadline * 0.9:
                continue
            if N == N0:
                seed = best_h.copy()
            else:
                seed = _seed_tent(N)
            rfunc = _R if N <= 400 else _R_fast
            h, r = _lbfgs_polish(seed, deadline, rfunc, maxiter=400)
            if r > best_R:
                best_R = r
                best_h = h.copy()
            # Follow with coordinate ascent
            h, r = _refine(h, deadline, rfunc, n_rounds=6)
            if r > best_R:
                best_R = r
                best_h = h.copy()

    # Phase 3: perturb-and-polish around the best
    if best_h is not None:
        base = best_h.copy()
        while time.process_time() < deadline:
            h = base.copy()
            # perturb a few entries multiplicatively
            k = max(1, h.size // 4)
            idx = rng.choice(h.size, size=min(k, h.size), replace=False)
            h[idx] *= np.exp(rng.normal(0, 0.1, size=idx.size))
            h = np.maximum(h, 0.0)
            rfunc = _R if h.size <= 400 else _R_fast
            h, r = _lbfgs_polish(h, deadline, rfunc, maxiter=200)
            if r > best_R + 1e-12:
                best_R = r
                best_h = h.copy()
                base = best_h.copy()
            else:
                break

    # Fallback
    if best_h is None:
        if start_h is not None:
            return start_h
        best_h = _seed_tent(7)

    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_fast(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    conv = fftconvolve(h, h)
    m = conv.max()
    if m <= 0:
        return 0.0
    Lext = np.empty(conv.size + 2)
    Lext[0] = 0.0
    Lext[1:-1] = conv
    Lext[-1] = 0.0
    a = Lext[:-1]
    b = Lext[1:]
    L2 = (a * a + a * b + b * b).sum() / 3.0
    return L2 / (s * s * m)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    # Seed: binomial profile
    N = 50000
    h = np.empty(N, dtype=float)
    h[0] = 1.0
    for n in range(N - 1):
        h[n + 1] = h[n] * (2.0 * n + 1.0) / (2.0 * n + 2.0)

    best_h = h.copy()
    best_R = _R_fast(h)

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0:
            try:
                r = _R_fast(hs)
                if r > best_R:
                    best_R = r
                    best_h = hs.copy()
            except Exception:
                pass

    N = best_h.size
    if N < 4:
        return best_h

    # Optimize a coarse set of control points in log-space, then refine.
    # Use piecewise-linear interpolation between control points so we can
    # reshape the entire profile with few variables.
    def build_from_ctrl(x, idx):
        vals = np.exp(np.clip(x, -12.0, 12.0))
        out = np.interp(np.arange(N), idx, vals)
        return out

    # Stage 1: coarse control grid over full domain
    n_ctrl = 200
    idx = np.linspace(0, N - 1, n_ctrl).astype(int)
    idx = np.unique(idx)
    x0 = np.log(np.maximum(best_h[idx], 1e-12))

    def negR_ctrl(x):
        return -_R_fast(build_from_ctrl(x, idx))

    try:
        res = minimize(
            negR_ctrl, x0, method='L-BFGS-B',
            bounds=[(-12.0, 12.0)] * x0.size,
            options={'maxiter': 400, 'ftol': 1e-13, 'gtol': 1e-11},
        )
        cand = build_from_ctrl(res.x, idx)
        r = _R_fast(cand)
        if r > best_R:
            best_R = r
            best_h = cand
    except Exception:
        pass

    # Stage 2: finer control grid warm-started from best_h
    if time.process_time() < deadline:
        n_ctrl = 1000
        idx = np.linspace(0, N - 1, n_ctrl).astype(int)
        idx = np.unique(idx)
        x0 = np.log(np.maximum(best_h[idx], 1e-12))

        def negR_ctrl2(x):
            return -_R_fast(build_from_ctrl(x, idx))

        try:
            res = minimize(
                negR_ctrl2, x0, method='L-BFGS-B',
                bounds=[(-12.0, 12.0)] * x0.size,
                options={'maxiter': 400, 'ftol': 1e-13, 'gtol': 1e-11},
            )
            cand = build_from_ctrl(res.x, idx)
            r = _R_fast(cand)
            if r > best_R:
                best_R = r
                best_h = cand
        except Exception:
            pass

    # Stage 3: full-resolution tail optimization in log-space
    if time.process_time() < deadline:
        M = min(8000, N)
        tail_idx = np.arange(N - M, N)
        x0 = np.log(np.maximum(best_h[tail_idx], 1e-12))
        prefix = best_h[:N - M].copy()

        def build_tail(x):
            out = np.empty(N, dtype=float)
            out[:N - M] = prefix
            out[N - M:] = np.exp(np.clip(x, -12.0, 12.0))
            return out

        def negR_tail(x):
            return -_R_fast(build_tail(x))

        try:
            res = minimize(
                negR_tail, x0, method='L-BFGS-B',
                bounds=[(-12.0, 12.0)] * M,
                options={'maxiter': 200, 'ftol': 1e-13, 'gtol': 1e-11},
            )
            cand = build_tail(res.x)
            r = _R_fast(cand)
            if r > best_R:
                best_R = r
                best_h = cand
        except Exception:
            pass

    # Stage 4: full-resolution head optimization in log-space
    if time.process_time() < deadline:
        M = min(8000, N)
        head_idx = np.arange(0, M)
        x0 = np.log(np.maximum(best_h[head_idx], 1e-12))
        suffix = best_h[M:].copy()

        def build_head(x):
            out = np.empty(N, dtype=float)
            out[:M] = np.exp(np.clip(x, -12.0, 12.0))
            out[M:] = suffix
            return out

        def negR_head(x):
            return -_R_fast(build_head(x))

        try:
            res = minimize(
                negR_head, x0, method='L-BFGS-B',
                bounds=[(-12.0, 12.0)] * M,
                options={'maxiter': 200, 'ftol': 1e-13, 'gtol': 1e-11},
            )
            cand = build_head(res.x)
            r = _R_fast(cand)
            if r > best_R:
                best_R = r
                best_h = cand
        except Exception:
            pass

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0:
            try:
                if _R_fast(hs) > best_R:
                    return hs
            except Exception:
                pass

    return best_h

