                    best_head_val, best_head = vx2, hx2

        if best_head_val > best_r:
            h_new = np.empty(N)
            h_new[:M] = np.maximum(best_head, 0.0)
            h_new[M:] = tail
            r_new = _R_fast(h_new)
            if r_new > best_r:
                best_h = h_new
                best_r = r_new

    print(f"best R = {best_r:.9f}, restarts = {restart}")
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_from_L(L, s):
    m = L.max()
    if m <= 0 or s <= 0:
        return 0.0
    L2 = (L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2).sum() / 3.0
    return L2 / (s * s * m)


def _R_fast(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    conv = fftconvolve(h, h)
    L = np.empty(conv.size + 2)
    L[0] = 0.0
    L[1:-1] = conv
    L[-1] = 0.0
    return _R_from_L(L, s)


def _binom(N):
    h = np.empty(N, dtype=float)
    h[0] = 1.0
    for n in range(N - 1):
        h[n + 1] = h[n] * (2.0 * n + 1.0) / (2.0 * n + 2.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 50000
    n = np.arange(N, dtype=float)

    best_h = None
    best_r = -1.0
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            best_r = rs
            best_h = hs.copy()

    def make_pow(alpha, p):
        return (n + alpha) ** (-p)

    # coarse grid scan
    alphas = np.linspace(0.1, 1.0, 100)
    ps = np.linspace(0.4, 0.6, 21)
    grid_best = (-1.0, 0.3, 0.5)
    for alpha in alphas:
        for p in ps:
            if time.process_time() > deadline:
                break
            h = make_pow(alpha, p)
            r = _R_fast(h)
            if r > grid_best[0]:
                grid_best = (r, alpha, p)
        if time.process_time() > deadline:
            break

    # refine with Nelder-Mead
    def negR(x):
        if time.process_time() > deadline:
            return 1.0
        alpha, p = x
        if alpha <= 0 or p <= 0:
            return 1.0
        return -_R_fast(make_pow(alpha, p))

    x0 = np.array([grid_best[1], grid_best[2]])
    try:
        res = minimize(negR, x0, method='Nelder-Mead',
                       options={'maxiter': 400, 'xatol': 1e-6, 'fatol': 1e-10})
        if -res.fun > grid_best[0]:
            grid_best = (-res.fun, res.x[0], res.x[1])
    except Exception:
        pass

    if grid_best[0] > best_r:
        h = make_pow(grid_best[1], grid_best[2])
        r = _R_fast(h)
        if r > best_r:
            best_h = h
            best_r = r

    if best_h is None:
        best_h = _binom(N)

    print(f"best R = {best_r:.9f}, alpha = {grid_best[1]:.4f}, p = {grid_best[2]:.4f}")
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_from_L(L, s):
    m = L.max()
    if m <= 0 or s <= 0:
        return 0.0
    L2 = (L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2).sum() / 3.0
    return L2 / (s * s * m)


def _R_fast(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    conv = fftconvolve(h, h)
    L = np.empty(conv.size + 2)
    L[0] = 0.0
    L[1:-1] = conv
    L[-1] = 0.0
    return _R_from_L(L, s)


def _binom(N):
    h = np.empty(N, dtype=float)
    h[0] = 1.0
    for n in range(N - 1):
        h[n + 1] = h[n] * (2.0 * n + 1.0) / (2.0 * n + 2.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    N = 50000
    base = _binom(N)
    base = base / base.max()

    best_h = base.copy()
    best_r = _R_fast(best_h)

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            if rs > best_r:
                best_r = rs
                best_h = hs.copy()

    # If we have a start of the right size, do endpoint optimization.
    if start is not None and np.asarray(start).size == N:
        h0 = np.asarray(start, dtype=float).copy()
        if h0.sum() > 0:
            M = 200
            idx = np.concatenate([np.arange(0, M), np.arange(N - M, N)])
            h0_safe = np.clip(h0, 1e-12, None)
            logh0 = np.log(h0_safe)

            def make_h(y):
                h = h0.copy()
                h[idx] = np.exp(logh0[idx] + y)
                return h

            def negR(y):
                if time.process_time() > deadline:
                    return 1.0
                return -_R_fast(make_h(y))

            y0 = np.zeros(idx.size)
            best_y = y0.copy()
            best_val = -_R_fast(make_h(y0))
            if best_val > best_r:
                best_r = best_val
                best_h = make_h(y0)

            bounds = [(-0.5, 0.5)] * idx.size

            # L-BFGS-B first
            try:
                res = minimize(negR, y0, method='L-BFGS-B', bounds=bounds,
                               options={'maxiter': 200, 'ftol': 1e-12, 'gtol': 1e-10})
                if -res.fun > best_val:
                    best_val = -res.fun
                    best_y = res.x.copy()
            except Exception:
                pass

            if time.process_time() < deadline:
                try:
                    res = minimize(negR, best_y, method='Powell', bounds=bounds,
                                   options={'maxiter': 100, 'xtol': 1e-8, 'ftol': 1e-12})
                    if -res.fun > best_val:
                        best_val = -res.fun
                        best_y = res.x.copy()
                except Exception:
                    pass

            if best_val > best_r:
                h_final = make_h(best_y)
                r_final = _R_fast(h_final)
                if r_final > best_r:
                    best_h = h_final
                    best_r = r_final

    print(f"best R = {best_r:.9f}")
    return best_h
